/*
  Pool LED Control 1.1
  Seeed XIAO ESP32-S3 + TWO addressable 24V WS2811 COB strips
  D0 / GPIO1 -> RGB strip DATA IN
  D1 / GPIO2 -> WHITE strip DATA IN
  USB-C -> 5V supply of the ESP32
  Both 24V LED negatives must share DC GND with ESP32 GND.

  Arduino libraries:
    - Adafruit NeoPixel
    - ESP32 by Espressif Systems (WiFi, WebServer, Preferences, ESPmDNS)

  First boot: WiFi SSID PoolLED-Setup, password PoolLED2026
  Open http://192.168.4.1/ on iPhone connected to this access point.
  WiFi configuration in panel allows joining home WiFi.

  NOTE: DATA is 3.3V. WS2811 may require a 3.3V->5V buffer.
  NEVER connect LED +24V to the ESP32.
*/

#include <Arduino.h>
#include <WiFi.h>
#include <WebServer.h>
#include <Preferences.h>
#include <ESPmDNS.h>
#include <Adafruit_NeoPixel.h>
#include <math.h>

constexpr uint8_t PIN_RGB = 1;    // XIAO D0
constexpr uint8_t PIN_WHITE = 2;  // XIAO D1
constexpr uint16_t MAX_DRIVERS = 400;
const char *AP_NAME = "PoolLED-Setup";
const char *AP_PASSWORD = "PoolLED2026"; // Change before use in shared environments.

// The LED-ONE strips cut every approximately 8.3 cm.
// 5 meters => about 60 WS2811 ICs; 10 meters => 120; 15 meters => 180.
// These are DRIVER COUNTS, not the number of physical COB chips.
uint16_t rgbDrivers = 60;
uint16_t whiteDrivers = 60;
// WHITE_MODE=1: one white section per WS2811 driver (R=G=B).
// WHITE_MODE=3: three independently controlled white sections per driver.
uint8_t whiteMode = 1;

Adafruit_NeoPixel rgbStrip(1, PIN_RGB, NEO_RGB + NEO_KHZ800);
Adafruit_NeoPixel whiteStrip(1, PIN_WHITE, NEO_RGB + NEO_KHZ800);
WebServer server(80);
Preferences prefs;
bool accessPointMode = false;
bool settingsDirty = false;
uint32_t dirtyTime = 0;
uint32_t lastFrame = 0;

struct LightingState {
  uint32_t rgbColor = 0x00AAFF;
  uint8_t rgbBrightness = 50;    // percent, 0-100
  uint8_t whiteBrightness = 60;  // percent, 0-100
  uint8_t rgbEffect = 0;         // 0 solid, 1 rainbow, 2 chase, 3 breathing, 4 wave
  uint8_t whiteEffect = 0;       // 0 solid, 1 chase, 2 breathing, 3 wave
  uint8_t speed = 45;            // 1-100
  uint8_t rgbOn = 0;
  uint8_t whiteOn = 0;
};
LightingState st;

