void markDirty() {
  settingsDirty = true;
  dirtyTime = millis();
  lastFrame = 0;
}

void saveSettings() {
  prefs.putBytes("light", &st, sizeof(st));
  prefs.putUShort("rgbN", rgbDrivers);
  prefs.putUShort("whiteN", whiteDrivers);
  prefs.putUChar("whiteM", whiteMode);
  settingsDirty = false;
}

uint16_t limitedDrivers(const String &value) {
  long count = value.toInt();
  if (count < 1) count = 1;
  if (count > MAX_DRIVERS) count = MAX_DRIVERS;
  return static_cast<uint16_t>(count);
}

void initStrips() {
  rgbStrip.updateLength(rgbDrivers);
  whiteStrip.updateLength(whiteDrivers);
  rgbStrip.begin();
  whiteStrip.begin();
  rgbStrip.clear();
  whiteStrip.clear();
  rgbStrip.show();
  whiteStrip.show();
}

float effectLevel(uint8_t effect, uint16_t i, uint16_t count, uint32_t now) {
  if (effect == 0) return 1.0f;
  float s = static_cast<float>(st.speed) / 42.0f;
  if (effect == 2) {
    float x = sinf((static_cast<float>(now) * 0.004f * s));
    return 0.10f + 0.90f * (0.5f + 0.5f * x);
  }
  if (effect == 1) {
    uint32_t stepMs = 550UL / (1UL + st.speed / 10UL);
    if (stepMs < 20) stepMs = 20;
    uint16_t head = static_cast<uint16_t>((now / stepMs) % count);
    uint16_t distance = (i + count - head) % count;
    uint16_t trail = count / 10;
    if (trail < 1) trail = 1;
    return distance < trail ? 1.0f : 0.02f;
  }
  float pos = 6.2831853f * 2.0f * static_cast<float>(i) / count;
  float x = sinf(pos - now * 0.0025f * s);
  return 0.08f + 0.92f * (0.5f + 0.5f * x);
}

uint8_t lit(uint8_t levelPercent, float effectFraction) {
  float v = (255.0f * levelPercent / 100.0f) * effectFraction;
  if (v <= 0) return 0;
  if (v >= 255) return 255;
  return static_cast<uint8_t>(v + 0.5f);
}

void renderFrame() {
  uint32_t now = millis();
  for (uint16_t i = 0; i < rgbDrivers; ++i) {
    if (!st.rgbOn || st.rgbBrightness == 0) {
      rgbStrip.setPixelColor(i, 0);
      continue;
    }
    uint32_t base = st.rgbColor;
    if (st.rgbEffect == 1) {
      uint16_t hue = static_cast<uint16_t>(now * (st.speed + 2UL) / 12UL +
                        static_cast<uint32_t>(i) * 65535UL / rgbDrivers);
      uint8_t b = lit(st.rgbBrightness, 1.0f);
      rgbStrip.setPixelColor(i, Adafruit_NeoPixel::ColorHSV(hue, 255, b));
    } else {
      uint8_t mode = st.rgbEffect == 2 ? 1 : st.rgbEffect == 3 ? 2 : st.rgbEffect == 4 ? 3 : 0;
      uint8_t bright = lit(st.rgbBrightness, effectLevel(mode, i, rgbDrivers, now));
      uint8_t r = static_cast<uint8_t>(((base >> 16) & 255UL) * bright / 255UL);
      uint8_t g = static_cast<uint8_t>(((base >> 8) & 255UL) * bright / 255UL);
      uint8_t b = static_cast<uint8_t>((base & 255UL) * bright / 255UL);
      rgbStrip.setPixelColor(i, rgbStrip.Color(r, g, b));
    }
  }
  rgbStrip.show();

  uint16_t virtualSections = whiteDrivers * (whiteMode == 3 ? 3 : 1);
  for (uint16_t i = 0; i < whiteDrivers; ++i) {
    uint8_t channels[3] = {0, 0, 0};
    for (uint8_t ch = 0; ch < 3; ++ch) {
      uint16_t virtualPixel = i * (whiteMode == 3 ? 3 : 1) + (whiteMode == 3 ? ch : 0);
      float f = effectLevel(st.whiteEffect, virtualPixel, virtualSections, now);
      channels[ch] = (st.whiteOn ? lit(st.whiteBrightness, f) : 0);
    }
    whiteStrip.setPixelColor(i, whiteStrip.Color(channels[0], channels[1], channels[2]));
  }
  whiteStrip.show();
}

void startWifi() {
  String ssid = prefs.getString("ssid", "");
  String password = prefs.getString("pass", "");
  if (ssid.length() > 0) {
    WiFi.mode(WIFI_STA);
    WiFi.setSleep(false);
    WiFi.begin(ssid.c_str(), password.c_str());
    Serial.print("Connecting to "); Serial.println(ssid);
    uint32_t began = millis();
    while (WiFi.status() != WL_CONNECTED && millis() - began < 12000UL) delay(250);
    if (WiFi.status() == WL_CONNECTED) {
      accessPointMode = false;
      if (MDNS.begin("pool-led")) MDNS.addService("http", "tcp", 80);
      Serial.print("Open http://pool-led.local/ or http://");
      Serial.print(WiFi.localIP()); Serial.println("/");
      return;
    }
    WiFi.disconnect(true);
  }
  WiFi.mode(WIFI_AP);
  WiFi.softAP(AP_NAME, AP_PASSWORD);
  accessPointMode = true;
  Serial.print("Connect to Wi-Fi: "); Serial.println(AP_NAME);
  Serial.print("Password: "); Serial.println(AP_PASSWORD);
  Serial.print("Open http://"); Serial.print(WiFi.softAPIP()); Serial.println("/");
}

String buildStateJSON() {
  char color[8];
  snprintf(color, sizeof(color), "#%06lX", static_cast<unsigned long>(st.rgbColor & 0xFFFFFFUL));
  String json;
  json.reserve(300);
  json += "{\"rgbOn\":" + String(st.rgbOn) + ",";
  json += "\"whiteOn\":" + String(st.whiteOn) + ",";
  json += "\"rgbBrightness\":" + String(st.rgbBrightness) + ",";
  json += "\"whiteBrightness\":" + String(st.whiteBrightness) + ",";
  json += "\"rgbEffect\":" + String(st.rgbEffect) + ",";
  json += "\"whiteEffect\":" + String(st.whiteEffect) + ",";
  json += "\"speed\":" + String(st.speed) + ",";
  json += "\"rgbColor\":\"" + String(color) + "\",";
  json += "\"rgbDrivers\":" + String(rgbDrivers) + ",";
  json += "\"whiteDrivers\":" + String(whiteDrivers) + ",";
  json += "\"whiteMode\":" + String(whiteMode) + ",";
  json += "\"apMode\":" + String(accessPointMode ? 1 : 0) + ",";
  json += "\"ip\":\"" + (accessPointMode ? WiFi.softAPIP().toString() : WiFi.localIP().toString()) + "\"}";
  return json;
}

void apiSet() {
  if (server.hasArg("rb")) st.rgbBrightness = constrain(server.arg("rb").toInt(), 0, 100);
  if (server.hasArg("wb")) st.whiteBrightness = constrain(server.arg("wb").toInt(), 0, 100);
  if (server.hasArg("sp")) st.speed = constrain(server.arg("sp").toInt(), 1, 100);
  if (server.hasArg("re")) st.rgbEffect = constrain(server.arg("re").toInt(), 0, 4);
  if (server.hasArg("we")) st.whiteEffect = constrain(server.arg("we").toInt(), 0, 3);
  if (server.hasArg("ron")) st.rgbOn = server.arg("ron").toInt() ? 1 : 0;
  if (server.hasArg("won")) st.whiteOn = server.arg("won").toInt() ? 1 : 0;
  if (server.hasArg("color")) {
    String value = server.arg("color");
    if (value.length() == 6) st.rgbColor = strtoul(value.c_str(), nullptr, 16) & 0xFFFFFFUL;
  }
  markDirty();
  server.send(200, "text/plain", "OK");
}

void apiPreset() {
  String scene = server.arg("name");
  if (scene == "day") {
    st.rgbOn = 0; st.whiteOn = 1; st.whiteBrightness = 100; st.whiteEffect = 0;
  } else if (scene == "relax") {
    st.rgbOn = 1; st.whiteOn = 1; st.rgbColor = 0x215EFF;
    st.rgbBrightness = 32; st.whiteBrightness = 17; st.rgbEffect = 4; st.whiteEffect = 0; st.speed = 23;
  } else if (scene == "party") {
    st.rgbOn = 1; st.whiteOn = 1; st.rgbBrightness = 90; st.whiteBrightness = 35;
    st.rgbEffect = 1; st.whiteEffect = 1; st.speed = 72;
  } else if (scene == "off") {
    st.rgbOn = 0; st.whiteOn = 0;
  } else if (scene == "favorite") {
    if (prefs.getBytesLength("favorite") == sizeof(st)) prefs.getBytes("favorite", &st, sizeof(st));
    else { server.send(404, "text/plain", "No favorite saved"); return; }
  } else { server.send(400, "text/plain", "Unknown preset"); return; }
  markDirty();
  server.send(200, "text/plain", "OK");
}

void apiConfig() {
  if (!server.hasArg("rgb") || !server.hasArg("white") || !server.hasArg("mode")) {
    server.send(400, "text/plain", "Missing values"); return;
  }
  rgbDrivers = limitedDrivers(server.arg("rgb"));
  whiteDrivers = limitedDrivers(server.arg("white"));
  whiteMode = server.arg("mode").toInt() == 3 ? 3 : 1;
  initStrips();
  markDirty();
  saveSettings();
  server.send(200, "text/plain", "OK");
}

void apiWifi() {
  String ssid = server.arg("ssid");
  String password = server.arg("password");
  if (ssid.isEmpty() || ssid.length() > 32 || (password.length() > 0 && password.length() < 8)) {
    server.send(400, "text/plain", "Invalid SSID or password"); return;
  }
  prefs.putString("ssid", ssid);
  prefs.putString("pass", password);
  server.send(200, "text/plain", "Rebooting");
  delay(500);
  ESP.restart();
}

void setup() {
  Serial.begin(115200);
  delay(150);
  prefs.begin("poolled", false);
  if (prefs.getBytesLength("light") == sizeof(st)) prefs.getBytes("light", &st, sizeof(st));
  rgbDrivers = prefs.getUShort("rgbN", 60);
  whiteDrivers = prefs.getUShort("whiteN", 60);
  whiteMode = prefs.getUChar("whiteM", 1);
  if (rgbDrivers < 1 || rgbDrivers > MAX_DRIVERS) rgbDrivers = 60;
  if (whiteDrivers < 1 || whiteDrivers > MAX_DRIVERS) whiteDrivers = 60;
  if (whiteMode != 3) whiteMode = 1;
  if (st.rgbBrightness > 100) st.rgbBrightness = 100;
  if (st.whiteBrightness > 100) st.whiteBrightness = 100;
  st.speed = constrain(static_cast<int>(st.speed), 1, 100);
  if (st.rgbEffect > 4) st.rgbEffect = 4;
  if (st.whiteEffect > 3) st.whiteEffect = 3;
  initStrips();
  renderFrame();
  startWifi();
  server.on("/", HTTP_GET, []() { server.send_P(200, "text/html; charset=utf-8", PAGE); });
  server.on("/api/state", HTTP_GET, []() { server.send(200, "application/json", buildStateJSON()); });
  server.on("/api/set", HTTP_POST, apiSet);
  server.on("/api/preset", HTTP_POST, apiPreset);
  server.on("/api/favorite", HTTP_POST, []() {
    prefs.putBytes("favorite", &st, sizeof(st));
    server.send(200, "text/plain", "OK");
  });
  server.on("/api/config", HTTP_POST, apiConfig);
  server.on("/api/wifi", HTTP_POST, apiWifi);
  server.onNotFound([]() { server.send(404, "text/plain", "Not found"); });
  server.begin();
  Serial.println("Pool LED Control ready");
}

void loop() {
  server.handleClient();
  if (lastFrame == 0 || millis() - lastFrame >= 35UL) {
    lastFrame = millis();
    renderFrame();
  }
  if (settingsDirty && millis() - dirtyTime >= 2500UL) saveSettings();
  delay(1);
}
